<h1><?= $staff?'Refund requests':'My refunds'?></h1><?php if(!$staff):?><form method="post" action="<?=e(url('/finance/refunds/request'))?>" class="card card-body mb-4"><?=csrf_field()?><label class="form-label">Eligible payment</label><select name="payment_reference" class="form-select" required><?php foreach($payments as $p)if($p['status']==='completed'):?><option value="<?=e($p['payment_reference'])?>"><?=e($p['payment_reference'].' — '.$p['currency'].' '.$p['amount'])?></option><?php endif;?></select><label class="form-label mt-2">Amount</label><input name="amount" class="form-control" required><label class="form-label mt-2">Reason</label><textarea name="reason" minlength="10" maxlength="1000" class="form-control" required></textarea><button class="btn btn-primary mt-3">Request refund</button></form><?php endif;?>
<?php foreach($requests as $rr):?><div class="card card-body mb-3"><strong><?=e($rr['request_reference'])?> — <?=e($rr['status'])?></strong><span><?=e($rr['payment_reference'].' · '.$rr['requested_amount'])?></span><p><?=e($rr['reason'])?></p><?php if($staff&&$rr['status']==='requested'):?><div class="d-flex gap-2"><form method="post" action="<?=e(url('/finance/refunds/'.$rr['request_reference'].'/approve'))?>"><?=csrf_field()?><button class="btn btn-success">Approve</button></form><form method="post" action="<?=e(url('/finance/refunds/'.$rr['request_reference'].'/reject'))?>"><?=csrf_field()?><input name="decision_reason" minlength="5" placeholder="Rejection reason" required><button class="btn btn-danger">Reject</button></form></div><?php elseif($staff&&$rr['status']==='approved'):?><form method="post" action="<?=e(url('/finance/refunds/'.$rr['request_reference'].'/process'))?>"><?=csrf_field()?><select name="method"><option value="eft">EFT</option><option value="cash">Cash</option><option value="other_manual">Other manual</option></select><input name="manual_reference" placeholder="Manual refund reference" required><button class="btn btn-primary">Record manual processing</button></form><?php endif;?></div><?php endforeach;?>
